package de.eldoria.bloodnight.generated;

import static de.eldoria.graph.std.runtime.Randoms.chance;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.BukkitRuntime;
import de.eldoria.bloodnight.graph.runtime.Registries;
import io.papermc.paper.registry.RegistryKey;
import org.bukkit.Sound;
import org.bukkit.entity.Entity;
import org.bukkit.entity.Player;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;
import org.bukkit.util.Vector;

public final class KnightZombieBehaviour implements CompiledBehaviour {
    private static final Sound ITEM_SHIELD_BLOCK = Registries.entry(RegistryKey.SOUND_EVENT, "minecraft:item.shield.block");

    private static final PotionEffectType SLOWNESS = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:slowness");

    private static final Sound BLOCK_BUBBLE_COLUMN_BUBBLE_POP = Registries.entry(RegistryKey.SOUND_EVENT, "minecraft:block.bubble_column.bubble_pop");

    private final MobContext context;

    public KnightZombieBehaviour(MobContext context) {
        this.context = context;
    }

    @Override
    public void onDamageByPlayer(EntityDamageByEntityEvent event) {
        // node #11 event.damage_by_player
        // node #17 flow.branch
        // node #12 event.damage_by_player
        final Entity attacker = BukkitRuntime.attacker(event);
        if (!(attacker instanceof Player)) return;
        // node #16 flow.branch
        if (!(chance(12.0d))) return;
        // node #13 cancellable.mutate
        event.setCancelled(true);
        // node #15 player.play_sound
        // node #14 cast
        final Player cast = (attacker instanceof Player ? (Player) attacker : null);
        cast.playSound(cast.getLocation(), ITEM_SHIELD_BLOCK, 15.0f, 1.0f);
        // node #18
    }

    @Override
    public void onHit(EntityDamageByEntityEvent event) {
        // node #33 event.hit
        // node #41 flow.branch
        // node #34 event.hit
        final Entity entity = event.getEntity();
        if (!(entity instanceof Player)) return;
        // node #40 flow.branch
        if (!(chance(15.0d))) return;
        // node #35 cancellable.mutate
        event.setCancelled(true);
        // node #37 entity.mutate
        // node #36 cast
        final Player cast = (entity instanceof Player ? (Player) entity : null);
        cast.setVelocity(new Vector(0.0d, 1.0d, 0.0d));
        // node #38 living_entity.apply_effect
        cast.addPotionEffect(new PotionEffect(SLOWNESS, (int) (1.0d * 20), 2, true, true));
        // node #39 player.play_sound
        cast.playSound(cast.getLocation(), BLOCK_BUBBLE_COLUMN_BUBBLE_POP, 15.0f, 3.0f);
        // node #42
    }
}
